arguments.command:
cd /tmp/sv-00217154458e4ff2beb81a9deaf5da71/symbols && \
# Get the real nearest exported symbol for each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== PC $addr ==="
  aarch64-linux-gnu-nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
    BEGIN { target_val = strtonum(target) }
    {
      val = strtonum("0x" $1)
      if (val <= target_val) {
        best_name = $3
        best_addr = $1
        best_offset = target_val - val
      }
    }
    END { if (best_name) printf "  %s+0x%x\n", best_name, best_offset }
  '
done

