arguments.command:
cd /tmp/sv-00217154458e4ff2beb81a9deaf5da71/symbols && \
# Show the symbols closest before and after each target address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  target=$(printf "%d" "$addr")
  echo "=== PC $addr ==="
  awk -v target="$target" '
    {
      val = strtonum("0x" $1)
      if (val <= target) { prev_name=$3; prev_addr=$1; prev_val=val }
      if (val > target && !found) { next_name=$3; next_addr=$1; found=1 }
    }
    END {
      printf "  Prev: 0x%s %s (offset +0x%x)\n", prev_addr, prev_name, target-prev_val
      printf "  Next: 0x%s %s\n", next_addr, next_name
    }
  ' all_syms.txt
done

